class MinStack {
private:
    // Storing pairs: {element, minimum from bottom up to this element}
    stack<pair<int, int>> st;

public:
    MinStack() {}

    // 1. Adding an element (Push):
    void push(int new_elem) {
        int new_min = st.empty() ? new_elem : min(new_elem, st.top().second);
        st.push({new_elem, new_min});
    }

    // 2. Removing an element (Pop):
    void pop() {
        if (!st.empty()) {
            st.pop();
        }
    }

    // 3. Inspecting the top element:
    int top() {
        return st.top().first;
    }

    // 4. Finding the minimum in O(1):
    int getMin() {
        return st.top().second;
    }

    // 5. Checking if the stack is empty:
    bool empty() {
        return st.empty();
    }
};

