class MinQueueDeque {
private:
    // Storing pairs: {element_value, added_index}
    deque<pair<int, int>> q;
    int cnt_added;
    int cnt_removed;

public:
    MinQueueDeque() : cnt_added(0), cnt_removed(0) {}

    // 1. Finding the minimum in O(1):
    int getMin() {
        return q.front().first;
    }

    // 2. Adding an element (Push / Enqueue):
    void push(int new_elem) {
        while (!q.empty() && q.back().first >= new_elem) {
            q.pop_back();
        }
        q.push_back({new_elem, cnt_added});
        cnt_added++;
    }

    // 3. Removing an element (Pop / Dequeue):
    void pop() {
        if (!q.empty() && q.front().second == cnt_removed) {
            q.pop_front();
        }
        cnt_removed++;
    }

    // 4. Checking if the queue is empty:
    bool empty() {
        return cnt_added == cnt_removed;
    }

    // 5. Total active element count:
    int size() {
        return cnt_added - cnt_removed;
    }
};

