using namespace std;

class MinQueueTwoStacks {
private:
    // s1 for enqueuing (tail), s2 for dequeuing (head)
    stack<pair<int, int>> s1, s2;

public:
    MinQueueTwoStacks() {}

    // 1. Finding the minimum in O(1):
    int getMin() {
        if (s1.empty() || s2.empty()) {
            return s1.empty() ? s2.top().second : s1.top().second;
        }
        return min(s1.top().second, s2.top().second);
    }

    // 2. Adding an element (Push / Enqueue):
    void push(int new_elem) {
        int cur_min = s1.empty() ? new_elem : min(new_elem, s1.top().second);
        s1.push({new_elem, cur_min});
    }

    // 3. Removing an element (Pop / Dequeue):
    int pop() {
        if (s2.empty()) {
            while (!s1.empty()) {
                int elem = s1.top().first;
                s1.pop();
                int cur_min = s2.empty() ? elem : min(elem, s2.top().second);
                s2.push({elem, cur_min});
            }
        }
        int removed = s2.top().first;
        s2.pop();
        return removed;
    }

    // 4. Checking if the queue is empty:
    bool empty() {
        return s1.empty() && s2.empty();
    }

    // 5. Total active element count:
    int size() {
        return s1.size() + s2.size();
    }
};

