using namespace std;

class DisjointSetUnion {
private:
    vector<int> parent;
    vector<int> rank;

public:
    // 1. Initialization (make_set for 0..n-1):
    DisjointSetUnion(int n) : parent(n), rank(n, 0) {
        iota(parent.begin(), parent.end(), 0);
    }

    // 2. Find representative with Path Compression:
    int find_set(int v) {
        if (v == parent[v]) {
            return v;
        }
        return parent[v] = find_set(parent[v]);
    }

    // 3. Union by Rank optimization:
    bool union_sets(int a, int b) {
        a = find_set(a);
        b = find_set(b);
        if (a == b) {
            return false; // Already in the same set
        }

        if (rank[a] < rank[b]) {
            swap(a, b);
        }
        parent[b] = a;
        if (rank[a] == rank[b]) {
            rank[a]++;
        }
        return true;
    }

    // 4. Connectivity query:
    bool is_connected(int a, int b) {
        return find_set(a) == find_set(b);
    }
};

