using namespace std;

class SegmentTree {
private:
    int n;
    vector<int> t;

    // 1. Recursive Tree Construction in O(N):
    void build(const vector<int>& a, int v, int tl, int tr) {
        if (tl == tr) {
            t[v] = a[tl];
        } else {
            int tm = (tl + tr) / 2;
            build(a, v * 2, tl, tm);
            build(a, v * 2 + 1, tm + 1, tr);
            t[v] = t[v * 2] + t[v * 2 + 1];
        }
    }

    // 2. Range Sum Query in O(log N):
    int sum(int v, int tl, int tr, int l, int r) {
        if (l > r) {
            return 0;
        }
        if (l == tl && r == tr) {
            return t[v];
        }
        int tm = (tl + tr) / 2;
        return sum(v * 2, tl, tm, l, min(r, tm)) +
               sum(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
    }

    // 3. Point Update in O(log N):
    void update(int v, int tl, int tr, int pos, int new_val) {
        if (tl == tr) {
            t[v] = new_val;
        } else {
            int tm = (tl + tr) / 2;
            if (pos <= tm)
                update(v * 2, tl, tm, pos, new_val);
            else
                update(v * 2 + 1, tm + 1, tr, pos, new_val);
            t[v] = t[v * 2] + t[v * 2 + 1];
        }
    }

public:
    SegmentTree(const vector<int>& a) {
        n = a.size();
        t.assign(4 * n, 0);
        if (n > 0) {
            build(a, 1, 0, n - 1);
        }
    }

    // Public query wrapper:
    int query(int l, int r) {
        return sum(1, 0, n - 1, l, r);
    }

    // Public point update wrapper:
    void modify(int pos, int new_val) {
        update(1, 0, n - 1, pos, new_val);
    }
};

