using namespace std;

class TopologicalSort {
private:
    int n;
    vector<vector<int>> adj;

    // Helper for DFS post-order traversal:
    void dfs(int v, vector<bool>& visited, vector<int>& order) {
        visited[v] = true;
        for (int u : adj[v]) {
            if (!visited[u]) {
                dfs(u, visited, order);
            }
        }
        order.push_back(v);
    }

public:
    TopologicalSort(int n) : n(n), adj(n) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
    }

    // 1. Kahn's In-Degree BFS Algorithm (with cycle detection):
    bool kahn(vector<int>& order) {
        order.clear();
        vector<int> indegree(n, 0);

        for (int u = 0; u < n; u++) {
            for (int v : adj[u]) {
                indegree[v]++;
            }
        }

        queue<int> q;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                q.push(i);
            }
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            order.push_back(u);

            for (int v : adj[u]) {
                if (--indegree[v] == 0) {
                    q.push(v);
                }
            }
        }

        // If not all vertices are processed, a directed cycle exists!
        return (int)order.size() == n;
    }

    // 2. DFS Post-Order Reversal Algorithm:
    vector<int> dfsSort() {
        vector<bool> visited(n, false);
        vector<int> order;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                dfs(i, visited, order);
            }
        }

        reverse(order.begin(), order.end());
        return order;
    }
};

