class ZeroOneBFS {
private:
    int n;
    const int INF = 1e9;
    vector<vector<pair<int, int>>> adj; // {neighbor, weight in {0, 1}}

public:
    ZeroOneBFS(int n) : n(n), adj(n) {}

    void addEdge(int u, int v, int weight, bool directed = true) {
        adj[u].push_back({v, weight});
        if (!directed) {
            adj[v].push_back({u, weight});
        }
    }

    // 1. 0-1 BFS Traversal in strictly O(V + E):
    vector<int> solve(int src) {
        vector<int> dist(n, INF);
        deque<int> dq;

        dist[src] = 0;
        dq.push_back(src);

        while (!dq.empty()) {
            int v = dq.front();
            dq.pop_front();

            // 2. Iterate through outgoing edges:
            for (auto& edge : adj[v]) {
                int to = edge.first;
                int weight = edge.second;

                if (dist[v] + weight < dist[to]) {
                    dist[to] = dist[v] + weight;

                    // 3. Push to FRONT if weight 0, push to BACK if weight 1:
                    if (weight == 0) {
                        dq.push_front(to);
                    } else {
                        dq.push_back(to);
                    }
                }
            }
        }

        return dist;
    }
};

#include <bits/stdc++.h>
using namespace std;

class CycleDetector {
private:
    int n;
    vector<vector<int>> adj;
    vector<int> parent;
    vector<char> color; // 0: White (Unvisited), 1: Gray (Active), 2: Black (Exited)
    int cycle_start, cycle_end;

    // 1. Directed 3-Color DFS Traversal:
    bool dfsDirected(int v) {
        color[v] = 1; // Mark Gray (currently in recursion stack)
        for (int u : adj[v]) {
            if (color[u] == 0) {
                parent[u] = v;
                if (dfsDirected(u)) return true;
            } else if (color[u] == 1) { // Encountered active ancestor -> Cycle!
                cycle_end = v;
                cycle_start = u;
                return true;
            }
        }
        color[v] = 2; // Mark Black (fully processed)
        return false;
    }

public:
    CycleDetector(int n) : n(n), adj(n) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
    }

    // 2. Cycle Detection and Path Extraction in O(V + E):
    bool findCycle(vector<int>& cycle) {
        color.assign(n, 0);
        parent.assign(n, -1);
        cycle_start = -1;

        for (int v = 0; v < n; v++) {
            if (color[v] == 0 && dfsDirected(v)) {
                break;
            }
        }

        if (cycle_start == -1) {
            return false; // Graph is acyclic
        }

        // 3. Reconstruct the cycle from cycle_end to cycle_start:
        cycle.clear();
        cycle.push_back(cycle_start);
        for (int v = cycle_end; v != cycle_start; v = parent[v]) {
            cycle.push_back(v);
        }
        cycle.push_back(cycle_start);
        reverse(cycle.begin(), cycle.end());
        return true;
    }
};

