class Knapsack01 {
private:
    int n, W;
    vector<int> weights;
    vector<int> values;

public:
    Knapsack01(int n, int capacity) : n(n), W(capacity) {}

    void addItem(int weight, int value) {
        weights.push_back(weight);
        values.push_back(value);
    }

    // 1. Space-Optimized O(W) 1D DP Solution:
    int solveSpaceOptimized() {
        vector<int> dp(W + 1, 0);

        for (int i = 0; i < n; i++) {
            // Strictly decreasing order ensures each item is used at most once:
            for (int j = W; j >= weights[i]; j--) {
                dp[j] = max(dp[j], dp[j - weights[i]] + values[i]);
            }
        }

        return dp[W];
    }

    // 2. 2D DP with Exact Item Reconstruction:
    pair<int, vector<int>> solveWithReconstruction() {
        vector<vector<int>> dp(n + 1, vector<int>(W + 1, 0));

        for (int i = 1; i <= n; i++) {
            int w = weights[i - 1];
            int v = values[i - 1];
            for (int j = 0; j <= W; j++) {
                dp[i][j] = dp[i - 1][j];
                if (j >= w) {
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - w] + v);
                }
            }
        }

        // Trace back chosen items:
        vector<int> chosen_items;
        int cur_w = W;
        for (int i = n; i >= 1; i--) {
            if (dp[i][cur_w] != dp[i - 1][cur_w]) {
                chosen_items.push_back(i - 1); // 0-based index of item
                cur_w -= weights[i - 1];
            }
        }
        reverse(chosen_items.begin(), chosen_items.end());

        return {dp[n][W], chosen_items};
    }
};

