class KnuthOptimization {
private:
    int n;
    const long long INF = 1e18;
    vector<vector<long long>> dp;
    vector<vector<int>> opt;

public:
    KnuthOptimization(int n) : n(n) {
        dp.assign(n, vector<long long>(n, 0));
        opt.assign(n, vector<int>(n, 0));
    }

    // Solves Optimal Range Splitting in O(N^2):
    long long solve(const vector<long long>& weights) {
        // Precompute prefix sums for cost function C(i, j) = sum(weights[i...j]):
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + weights[i];
        }

        auto cost = [&](int i, int j) -> long long {
            return pref[j + 1] - pref[i];
        };

        // 1. Base cases: intervals of length 1 (cost 0)
        for (int i = 0; i < n; i++) {
            opt[i][i] = i;
            dp[i][i] = 0;
        }

        // 2. Process by increasing interval length from 2 to n:
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = INF;

                // 3. Knuth-Yao bounded search range:
                int k_start = opt[i][j - 1];
                int k_end = (i + 1 <= j) ? opt[i + 1][j] : j - 1;

                for (int k = k_start; k <= min(j - 1, k_end); k++) {
                    long long cur_cost = dp[i][k] + dp[k + 1][j] + cost(i, j);
                    if (cur_cost < dp[i][j]) {
                        dp[i][j] = cur_cost;
                        opt[i][j] = k; // Record optimal splitting point
                    }
                }
            }
        }

        return dp[0][n - 1];
    }
};

