class ZAlgorithm {
public:
    ZAlgorithm() {}

    // 1. Compute Z-array in O(N):
    vector<int> computeZ(const string& s) {
        int n = s.length();
        vector<int> z(n, 0);
        int l = 0, r = 0; // Active segment match window [l, r)

        for (int i = 1; i < n; i++) {
            // 2. Initialize using previous segment match if within window:
            if (i < r) {
                z[i] = min(r - i, z[i - l]);
            }

            // 3. Trivial character expansion beyond boundary r:
            while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
                z[i]++;
            }

            // 4. Update rightmost segment match window:
            if (i + z[i] > r) {
                l = i;
                r = i + z[i];
            }
        }

        return z;
    }

    // 5. Pattern Matching in O(N + M):
    vector<int> search(const string& text, const string& pattern) {
        int n = pattern.length();
        int m = text.length();
        vector<int> occurrences;
        if (n == 0 || m < n) return occurrences;

        // Composite string with sentinel delimiter:
        string s = pattern + "$" + text;
        vector<int> z = computeZ(s);

        // Any index where z[i] == pattern length indicates an occurrence:
        for (int i = n + 1; i < (int)s.length(); i++) {
            if (z[i] == n) {
                occurrences.push_back(i - n - 1);
            }
        }

        return occurrences;
    }
};

#include <bits/stdc++.h>
using namespace std;

class StringHash {
private:
    int n;
    const int P1 = 31, M1 = 1e9 + 7;
    const int P2 = 37, M2 = 1e9 + 9;

    vector<long long> h1, h2;
    vector<long long> p_pow1, p_pow2;

public:
    // 1. Precompute Prefix Hashes and Prime Powers in O(N):
    StringHash(const string& s) : n(s.length()) {
        h1.assign(n + 1, 0);
        h2.assign(n + 1, 0);
        p_pow1.assign(n + 1, 1);
        p_pow2.assign(n + 1, 1);

        for (int i = 0; i < n; i++) {
            h1[i + 1] = (h1[i] + (s[i] - 'a' + 1) * p_pow1[i]) % M1;
            h2[i + 1] = (h2[i] + (s[i] - 'a' + 1) * p_pow2[i]) % M2;
            p_pow1[i + 1] = (p_pow1[i] * P1) % M1;
            p_pow2[i + 1] = (p_pow2[i] * P2) % M2;
        }
    }

    // 2. Query Substring Hash for S[l...r] in O(1):
    pair<long long, long long> getHash(int l, int r) {
        long long hash1 = (h1[r + 1] - h1[l] + M1) % M1;
        long long hash2 = (h2[r + 1] - h2[l] + M2) % M2;
        return {hash1, hash2};
    }

    // 3. Rabin-Karp Substring Matching in O(N + M):
    static vector<int> rabinKarp(const string& text, const string& pattern) {
        int n = text.length();
        int m = pattern.length();
        vector<int> occurrences;
        if (m == 0 || n < m) return occurrences;

        StringHash textHash(text);
        StringHash patHash(pattern);
        auto target = patHash.getHash(0, m - 1);

        for (int i = 0; i <= n - m; i++) {
            auto cur = textHash.getHash(i, i + m - 1);
            // Align prime powers: cur * 1 vs target * P^i
            long long aligned1 = (target.first * textHash.p_pow1[i]) % textHash.M1;
            long long aligned2 = (target.second * textHash.p_pow2[i]) % textHash.M2;

            if (cur.first == aligned1 && cur.second == aligned2) {
                occurrences.push_back(i);
            }
        }

        return occurrences;
    }
};

